#include <concepts>
#include <iostream>
#include <limits>
#include <optional>
#include <type_traits>

template<class T>
concept UnsignedAmount = std::unsigned_integral<T>
    && (!std::same_as<std::remove_cv_t<T>, bool>);

template<UnsignedAmount T>
std::optional<T> checked_add(T left, T right) {
    if (right > std::numeric_limits<T>::max() - left) {
        return std::nullopt;
    }
    return static_cast<T>(left + right);
}

int main() {
    std::cout << *checked_add(3U, 4U) << '\n';
    const auto high = std::numeric_limits<unsigned int>::max();
    std::cout << std::boolalpha << checked_add(high, 1U).has_value() << '\n';
    const auto small = checked_add(static_cast<unsigned char>(10), static_cast<unsigned char>(20));
    std::cout << static_cast<unsigned int>(*small) << '\n';
    static_assert(!UnsignedAmount<bool>);
    static_assert(!UnsignedAmount<int>);
}

#include <array>
#include <climits>
#include <iostream>
#include <optional>

static_assert(CHAR_BIT == 8, "this four-octet format requires 8-bit bytes");
using Wire32 = std::array<unsigned char, 4>;
constexpr unsigned long long wire_max = 0xFFFFFFFFULL;

std::optional<Wire32> encode_be32(unsigned long long value) {
    if (value > wire_max) {
        return std::nullopt;
    }
    return Wire32{
        static_cast<unsigned char>((value >> 24) & 0xFFULL),
        static_cast<unsigned char>((value >> 16) & 0xFFULL),
        static_cast<unsigned char>((value >> 8) & 0xFFULL),
        static_cast<unsigned char>(value & 0xFFULL)
    };
}

unsigned long long decode_be32(const Wire32& bytes) {
    unsigned long long value = 0;
    for (const auto byte : bytes) {
        value = value * 256ULL + byte;
    }
    return value;
}

int main() {
    const auto encoded = encode_be32(0x01020304ULL);
    for (const auto byte : *encoded) {
        std::cout << static_cast<unsigned int>(byte) << '\n';
    }
    std::cout << decode_be32(*encoded) << '\n';
    std::cout << std::boolalpha << encode_be32(wire_max + 1ULL).has_value() << '\n';
}

#include <iostream>
#include <memory>
#include <stdexcept>
#include <utility>
// Header section: users need only this declaration and <memory>.
class Quote {
    class Impl;
    std::unique_ptr<Impl> p_;
public:
    explicit Quote(int cents);
    ~Quote();
    Quote(Quote&&) noexcept;
    Quote& operator=(Quote&&) noexcept;
    Quote(const Quote&) = delete;
    Quote& operator=(const Quote&) = delete;
    int cents() const; // moved-from objects reject this query
};
// Implementation section: in a real library, move to quote.cpp.
class Quote::Impl {
public:
    int cents;
    explicit Impl(int x) : cents(x) {
        if (x < 0) throw std::invalid_argument("negative cents");
    }
};
Quote::Quote(int x) : p_(std::make_unique<Impl>(x)) {}
Quote::~Quote() = default;
Quote::Quote(Quote&&) noexcept = default;
Quote& Quote::operator=(Quote&&) noexcept = default;
int Quote::cents() const {
    if (!p_) throw std::logic_error("moved-from quote");
    return p_->cents;
}
int main() {
    int cases = 0;
    for (int x = 0; x <= 1000; ++x) {
        Quote a(x);
        Quote b(std::move(a));
        if (b.cents() != x) return 1;
        try { (void)a.cents(); return 2; } catch (const std::logic_error&) {}
        Quote c(0); c = std::move(b);
        if (c.cents() != x) return 3;
        ++cases;
    }
    try { Quote bad(-1); return 4; } catch (const std::invalid_argument&) {}
    std::cout << cases << " ownership transfers; negative rejected\n";
}

#include <iostream>
#include <type_traits>

struct Identity {
    int operator()(int x) const noexcept { return x; }
};
struct Cap10 {
    int operator()(int x) const noexcept { return x > 10 ? 10 : x; }
};
template<class Derived> class Twice {
    friend Derived;
    Twice() = default; // only the intended derived can construct its base
    Twice(const Twice&) = default;
    Twice& operator=(const Twice&) = default;
protected:
    ~Twice() = default; // prevent standalone sliced base objects
public:
    int twice(int x) const noexcept {
        // CRTP precondition: this really is a Derived base subobject.
        return static_cast<const Derived&>(*this).adjust(x) * 2;
    }
};
template<class Policy> class StaticAdjust final : public Twice<StaticAdjust<Policy>> {
    Policy policy_;
public:
    int adjust(int x) const noexcept { return policy_(x); }
};
struct DynamicAdjust {
    virtual int adjust(int x) const noexcept = 0;
    virtual ~DynamicAdjust() = default;
};
struct DynamicCap final : DynamicAdjust {
    int adjust(int x) const noexcept override { return x > 10 ? 10 : x; }
};
int runtime_twice(const DynamicAdjust& p, int x) noexcept { return 2 * p.adjust(x); }

// Tags select implementations at compile time, not from a live market value.
int units(int x, std::true_type) noexcept { return x; }
int units(int x, std::false_type) noexcept { return x * 100; }
template<bool AlreadyCents> int to_cents(int x) noexcept {
    return units(x, std::bool_constant<AlreadyCents>{});
}
int main() {
    StaticAdjust<Cap10> capped;
    StaticAdjust<Identity> identity;
    DynamicCap dyn;
    int checksum = 0;
    for (int x = 0; x <= 100; ++x) {
        const int wanted = x < 10 ? x : 10;
        if (capped.twice(x) != 2 * wanted || identity.twice(x) != 2*x) return 1;
        if (runtime_twice(dyn, x) != capped.twice(x)) return 2;
        if (to_cents<true>(x) != x || to_cents<false>(x) != 100*x) return 3;
        checksum += capped.twice(x);
    }
    std::cout << "101 equivalent dispatch cases; checksum=" << checksum << '\n';
    std::cout << to_cents<true>(7) << ' ' << to_cents<false>(7) << '\n';
}
